/// <summary>
/// MPJ_28155_SalesFinalisation 3.6.9 Post delivery note
/// </summary>
[ExtensionOf(tableStr(CustPackingSlipJour))]
final class METCustPackingSlipJourTbl_Extension
{
}

Method.Source:
    /// <summary>
    /// Init delivery note journal header load and shipment ID
    /// </summary>
    /// <param name = "_salesTable"><c>SalesTable</c> record to initialize from</param>
    void  initFromSalesTable(SalesTable _salesTable)
    {
        next initFromSalesTable(_salesTable);

        // retrieve the shipment from sales order id
        METShipmentTable METShipmentTable = METShipmentTable::findSalesId(_salesTable.SalesId);

        // init delivery note journal header load and shipment ID
        this.METLoadId = METShipmentTable.LoadId;
        this.METShipmentId = METShipmentTable.ShipmentId;
    }
